import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  AlertTriangle,
  Bell,
  BookOpen,
  CalendarDays,
  CheckCircle2,
  ChevronDown,
  ChevronRight,
  FileText,
  HeartHandshake,
  Inbox,
  MessageCircle,
  ShieldCheck,
  Sparkles,
  TrendingUp,
  UsersRound,
  X,
} from 'lucide-react';
import api from './api/auth.js';
import { getApiErrorMessage } from './api/errorMessage.js';

function StudentSelector({ options, selected, onChange }) {
  if (!options.length) return null;
  const current = options.find((item) => item.id === selected) || options[0];
  const initials = `${current.name?.[0] || 'C'}`.toUpperCase();

  return (
    <div className="parent-student-selector">
      <div className="parent-child-avatar mint">{initials}</div>
      <label>
        <span>Viewing student</span>
        <select
          value={current.id}
          onChange={(event) => onChange(event.target.value)}
        >
          {options.map((child) => (
            <option key={child.id} value={child.id}>
              {child.name} ({child.admissionNumber})
            </option>
          ))}
        </select>
      </label>
      <ChevronDown aria-hidden="true" />
    </div>
  );
}

export default function ParentClassroomWorkspace() {
  const [children, setChildren] = useState([]);
  const [selectedId, setSelectedId] = useState('');
  const [classrooms, setClassrooms] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [activeTab, setActiveTab] = useState('overview');
  const [toast, setToast] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const notify = (message) => {
    setToast(message);
    window.setTimeout(() => setToast(''), 2600);
  };

  const loadPortal = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const response = await api.get('/parents/me');
      const data = response.data.data;
      const parsedChildren = (data.children || []).map((link) => ({
        id: link.student.id,
        name: `${link.student.profile?.firstName ?? ''} ${link.student.profile?.lastName ?? ''}`.trim() || 'Student',
        admissionNumber: link.student.admissionNumber,
        relationship: link.relationship,
        status: link.student.status,
        permissions: link.permissions,
      }));
      setChildren(parsedChildren);
      if (parsedChildren.length > 0 && !selectedId) {
        setSelectedId(parsedChildren[0].id);
      }
    } catch (requestError) {
      setError(getApiErrorMessage(requestError, 'Unable to load family portal'));
    } finally {
      setLoading(false);
    }
  }, [selectedId]);

  const loadClassroomData = useCallback(async () => {
    try {
      const classroomsRes = await api.get('/lms/classrooms');
      const rooms = classroomsRes.data.data || [];
      setClassrooms(rooms);

      if (rooms.length > 0) {
        const assignmentRes = await api.get('/lms/assignments', {
          params: { classroomId: rooms[0].id, status: 'PUBLISHED' },
        });
        setAssignments(assignmentRes.data.data || []);
      }
    } catch {
      // Gracefully retain empty lists if student LMS endpoints require specific student scope
    }
  }, []);

  useEffect(() => {
    loadPortal();
  }, [loadPortal]);

  useEffect(() => {
    if (selectedId) {
      loadClassroomData();
    }
  }, [loadClassroomData, selectedId]);

  const selectedChild = useMemo(
    () => children.find((c) => c.id === selectedId) || children[0] || null,
    [children, selectedId]
  );

  return (
    <main className="parent-classroom-shell">
      <header className="parent-classroom-header">
        <div>
          <p className="eyebrow">Parent classroom · Read-only view</p>
          <h1>Stay close to the learning.</h1>
          <p>
            Monitor progress, celebrate wins, and understand what your learner needs next. Your
            access is limited to linked student records.
          </p>
        </div>
        <div className="parent-header-actions">
          <span className="parent-privacy">
            <ShieldCheck aria-hidden="true" /> Guardian access verified
          </span>
          <button
            className="parent-icon-button"
            onClick={() => notify('You have 4 new classroom updates.')}
            aria-label="Open notifications"
          >
            <Bell aria-hidden="true" />
            <i />
          </button>
          <button
            className="parent-primary"
            onClick={() => notify('Message composer opened for the homeroom team.')}
          >
            <MessageCircle aria-hidden="true" /> Message school
          </button>
        </div>
      </header>

      <div className="parent-toolbar">
        <StudentSelector
          options={children}
          selected={selectedId}
          onChange={(id) => setSelectedId(id)}
        />
        <div className="parent-toolbar-links">
          <button
            onClick={() => setActiveTab('overview')}
            className={activeTab === 'overview' ? 'active' : ''}
          >
            Overview
          </button>
          <button
            onClick={() => setActiveTab('attendance')}
            className={activeTab === 'attendance' ? 'active' : ''}
          >
            Attendance
          </button>
        </div>
        <span className="parent-last-sync">
          <CheckCircle2 aria-hidden="true" /> Synced live from LMS
        </span>
      </div>

      {error && <div style={{ background: '#3c181c', color: '#ffb3ba', padding: '12px', borderRadius: '8px', marginBottom: '16px' }}>{error}</div>}

      {activeTab === 'overview' && (
        <>
          <section className="parent-stat-grid" aria-label="Student summary">
            <article className="parent-stat mint">
              <span>Active Classrooms</span>
              <strong>{classrooms.length}</strong>
              <small>
                <TrendingUp aria-hidden="true" /> Enrolled spaces
              </small>
            </article>
            <article className="parent-stat blue">
              <span>Published Assignments</span>
              <strong>{assignments.length}</strong>
              <small>
                <CalendarDays aria-hidden="true" /> Active classwork
              </small>
            </article>
            <article className="parent-stat amber">
              <span>Learner Status</span>
              <strong>{selectedChild?.status ?? 'ACTIVE'}</strong>
              <small>
                <AlertTriangle aria-hidden="true" /> {selectedChild?.relationship ?? 'Parent'}
              </small>
            </article>
            <article className="parent-stat violet">
              <span>Academic Access</span>
              <strong>{selectedChild?.permissions?.academic ? 'Granted' : 'Restricted'}</strong>
              <small>
                <Inbox aria-hidden="true" /> Verifiable access
              </small>
            </article>
          </section>
          <div className="parent-main-grid">
            <div className="parent-column">
              <section className="parent-panel">
                <div className="parent-section-heading">
                  <div>
                    <span className="section-kicker">Enrolled learning spaces</span>
                    <h2>Digital Classrooms</h2>
                  </div>
                  <a
                    className="parent-link"
                    href="/parent-portal"
                  >
                    <UsersRound aria-hidden="true" /> Family Portal
                  </a>
                </div>
                <div className="parent-schedule">
                  {classrooms.length === 0 && (
                    <p style={{ color: '#9aabc0', fontSize: '13px' }}>No active digital classrooms found for this student.</p>
                  )}
                  {classrooms.map((item) => (
                    <div className="parent-schedule-item" key={item.id}>
                      <time>{item.code}</time>
                      <i className="parent-schedule-line mint" />
                      <div>
                        <strong>{item.name}</strong>
                        <small>{item._count?.memberships ?? 0} members · {item.description || 'Active classroom'}</small>
                      </div>
                      <span className="parent-badge live">ACTIVE</span>
                    </div>
                  ))}
                </div>
              </section>
              <section className="parent-panel">
                <div className="parent-section-heading">
                  <div>
                    <span className="section-kicker">Learning activity</span>
                    <h2>Assignments and classwork</h2>
                  </div>
                </div>
                <div className="parent-assignment-list">
                  {assignments.length === 0 && (
                    <p style={{ color: '#9aabc0', fontSize: '13px' }}>No published assignments available.</p>
                  )}
                  {assignments.map((item) => (
                    <button
                      className="parent-assignment"
                      key={item.id}
                      onClick={() => setSelectedAssignment(item)}
                    >
                      <span className="parent-work-icon mint">
                        <FileText aria-hidden="true" />
                      </span>
                      <span>
                        <strong>{item.title}</strong>
                        <small>
                          {item.type} · {item.points} pts {item.dueAt ? `· Due ${new Date(item.dueAt).toLocaleDateString()}` : ''}
                        </small>
                      </span>
                      <span className="parent-badge mint">{item.status}</span>
                      <ChevronRight aria-hidden="true" />
                    </button>
                  ))}
                </div>
              </section>
            </div>
            <div className="parent-column">
              <section className="parent-panel parent-progress">
                <div className="parent-section-heading">
                  <div>
                    <span className="section-kicker">Term progress</span>
                    <h2>Academic snapshot</h2>
                  </div>
                  <Sparkles aria-hidden="true" className="parent-spark" />
                </div>
                <div className="parent-score">
                  <strong>{selected.average}</strong>
                  <span>overall average</span>
                  <b>On track</b>
                </div>
                <div className="parent-progress-bar">
                  <i />
                </div>
                <div className="parent-progress-footer">
                  <span>Term 2 of 3</span>
                  <span>+4 points since Term 1</span>
                </div>
                <div className="parent-mini-chart" aria-label="Academic progress trend">
                  {[44, 55, 50, 62, 68, 76, 81, 86].map((height, index) => (
                    <i key={index} style={{ height: `${height}%` }} />
                  ))}
                </div>
                <div className="parent-progress-footer">
                  <span>Jan 12</span>
                  <span>Now</span>
                </div>
              </section>
              <section className="parent-panel">
                <div className="parent-section-heading">
                  <div>
                    <span className="section-kicker">Connected classroom</span>
                    <h2>Classes and teachers</h2>
                  </div>
                  <button
                    className="parent-link"
                    onClick={() => notify('Teacher directory opened.')}
                  >
                    <UsersRound aria-hidden="true" /> Directory
                  </button>
                </div>
                <div className="parent-class-list">
                  {classes.map((item) => (
                    <button
                      className="parent-class"
                      key={item.name}
                      onClick={() => notify(`Opening ${item.name} progress.`)}
                    >
                      <span className={`parent-class-mark ${item.accent}`}>{item.initials}</span>
                      <span>
                        <strong>{item.name}</strong>
                        <small>{item.teacher}</small>
                      </span>
                      <b>{item.score}</b>
                      <ChevronRight aria-hidden="true" />
                    </button>
                  ))}
                </div>
              </section>
            </div>
          </div>
        </>
      )}
      {activeTab === 'attendance' && (
        <section className="parent-empty-panel">
          <CalendarDays aria-hidden="true" />
          <h2>Attendance overview</h2>
          <p>
            {selected.name} has attended 96% of scheduled lessons this term. Attendance details,
            excused absences, and upcoming school days are available in the full attendance report.
          </p>
          <button className="parent-primary" onClick={() => notify('Attendance report requested.')}>
            Request full report
          </button>
        </section>
      )}
      {activeTab === 'messages' && (
        <section className="parent-empty-panel">
          <HeartHandshake aria-hidden="true" />
          <h2>School messages</h2>
          <p>
            Two teacher updates are waiting for your review. Messages are scoped to {selected.name}
            &apos;s linked classroom team.
          </p>
          <button className="parent-primary" onClick={() => notify('Opening message center.')}>
            Open message center
          </button>
        </section>
      )}
      <footer className="parent-footer">
        <span>
          <ShieldCheck aria-hidden="true" /> You are viewing linked classroom data only.
        </span>
        <span>Need help? Contact your school administrator.</span>
      </footer>
      {selectedAssignment && (
        <div
          className="parent-modal"
          role="presentation"
          onClick={() => setSelectedAssignment(null)}
        >
          <section
            className="parent-modal-card"
            role="dialog"
            aria-modal="true"
            aria-labelledby="parent-assignment-title"
            onClick={(event) => event.stopPropagation()}
          >
            <button
              className="parent-icon-button modal-close"
              onClick={() => setSelectedAssignment(null)}
              aria-label="Close assignment"
            >
              <X aria-hidden="true" />
            </button>
            <span className={`parent-work-icon ${selectedAssignment.accent}`}>
              <BookOpen aria-hidden="true" />
            </span>
            <h2 id="parent-assignment-title">{selectedAssignment.title}</h2>
            <p>
              {selectedAssignment.subject} · {selectedAssignment.due}
            </p>
            <div className="parent-note">
              <Sparkles aria-hidden="true" />
              <span>
                <strong>Family view</strong>
                <small>
                  Teacher feedback and submission details will appear here once released by the
                  school.
                </small>
              </span>
            </div>
            <button
              className="parent-primary"
              onClick={() => {
                setSelectedAssignment(null);
                notify('Opening the linked classroom resource.');
              }}
            >
              Open classroom resource
            </button>
          </section>
        </div>
      )}
      {toast && (
        <div className="parent-toast" role="status">
          <CheckCircle2 aria-hidden="true" /> {toast}
        </div>
      )}
    </main>
  );
}

/* eslint-disable react/prop-types */
import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Bell,
  BookOpen,
  CalendarDays,
  CheckCircle2,
  ChevronRight,
  Clock3,
  FileText,
  GraduationCap,
  Inbox,
  MapPin,
  MoreHorizontal,
  RefreshCw,
  Search,
  Sparkles,
  Target,
  TrendingUp,
  X,
} from 'lucide-react';
import api from './api/auth.js';
import { useAuth } from './context/AuthContext.jsx';
import { getApiErrorMessage } from './api/errorMessage.js';

function ShieldCheckIcon() {
  return <Sparkles size={14} />;
}

function Badge({ children, tone = '' }) {
  return <span className={`student-badge ${tone}`}>{children}</span>;
}
function SectionHeader({ eyebrow, title, action }) {
  return (
    <div className="student-section-header">
      <div>
        <span className="section-kicker">{eyebrow}</span>
        <h2>{title}</h2>
      </div>
      {action}
    </div>
  );
}

export default function StudentHomeDashboard() {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('Overview');
  const [showNotifications, setShowNotifications] = useState(false);
  const [query, setQuery] = useState('');
  const [classrooms, setClassrooms] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [calendarEvents, setCalendarEvents] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [schoolId, setSchoolId] = useState(() => sessionStorage.getItem('sais.schoolId') || '');

  const headers = schoolId ? { 'x-school-id': schoolId } : {};

  const loadData = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [classroomsRes, notificationsRes] = await Promise.allSettled([
        api.get('/lms/classrooms', { headers }),
        api.get('/communication/unread-count', { headers }),
      ]);

      if (notificationsRes.status === 'fulfilled') {
        setUnreadCount(notificationsRes.value.data.data?.unreadCount ?? 0);
      }

      if (classroomsRes.status === 'fulfilled') {
        const rooms = classroomsRes.value.data.data || [];
        setClassrooms(rooms);

        if (rooms.length > 0) {
          const primaryRoomId = rooms[0].id;
          const calendarStart = new Date();
          const calendarEnd = new Date();
          calendarEnd.setDate(calendarEnd.getDate() + 30);

          const [assignmentRes, calendarRes] = await Promise.allSettled([
            api.get('/lms/assignments', {
              headers,
              params: { classroomId: primaryRoomId, status: 'PUBLISHED' },
            }),
            api.get('/lms/calendar', {
              headers,
              params: {
                classroomId: primaryRoomId,
                start: calendarStart.toISOString(),
                end: calendarEnd.toISOString(),
              },
            }),
          ]);

          if (assignmentRes.status === 'fulfilled') {
            setAssignments(assignmentRes.value.data.data || []);
          }
          if (calendarRes.status === 'fulfilled') {
            setCalendarEvents(calendarRes.value.data.data || []);
          }
        }
      }
    } catch (requestError) {
      setError(getApiErrorMessage(requestError, 'Unable to load student learning data'));
    } finally {
      setLoading(false);
    }
  }, [schoolId]);

  useEffect(() => {
    sessionStorage.setItem('sais.schoolId', schoolId);
    loadData();
  }, [loadData, schoolId]);

  const initials = useMemo(() => {
    if (!user) return 'ST';
    const first = user.firstName?.[0] || 'S';
    const last = user.lastName?.[0] || 'T';
    return `${first}${last}`.toUpperCase();
  }, [user]);

  const filteredClasses = useMemo(
    () =>
      classrooms.filter((item) =>
        `${item.name} ${item.code} ${item.description || ''}`
          .toLowerCase()
          .includes(query.toLowerCase())
      ),
    [classrooms, query]
  );

  return (
    <main className="student-home-shell">
      <header className="student-home-header">
        <div className="student-identity">
          <div className="student-avatar">{initials}</div>
          <div>
            <span className="eyebrow">{new Date().toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}</span>
            <h1>Good morning, {user?.firstName ?? 'Student'}.</h1>
            <p>Your learning day is ready. Here’s what needs your attention.</p>
          </div>
        </div>
        <div className="student-header-actions">
          <button
            className="student-icon-button"
            aria-label="Open notifications"
            onClick={() => setShowNotifications(true)}
          >
            <Bell />
            {unreadCount > 0 && <i />}
          </button>
          <a className="student-primary" href="/student-submission-center">
            <BookOpen /> My work
          </a>
        </div>
      </header>
      <nav className="student-tabs" aria-label="Student dashboard sections">
        {['Overview', 'My classes', 'Progress'].map((tab) => (
          <button
            className={activeTab === tab ? 'active' : ''}
            key={tab}
            onClick={() => setActiveTab(tab)}
          >
            {tab}
          </button>
        ))}
      </nav>
      {activeTab === 'Overview' && (
        <>
          <section className="student-stats">
            <article>
              <span>Enrolled classrooms</span>
              <strong>{classrooms.length}</strong>
              <small>
                <CheckCircle2 /> Active learner spaces
              </small>
            </article>
            <article className="mint">
              <span>Published work</span>
              <strong>{assignments.length}</strong>
              <small>
                <TrendingUp /> Active assignments
              </small>
            </article>
            <article className="violet">
              <span>Calendar events</span>
              <strong>{calendarEvents.length}</strong>
              <small>
                <Clock3 /> Upcoming deadlines & lessons
              </small>
            </article>
            <article className="amber">
              <span>Unread updates</span>
              <strong>{unreadCount}</strong>
              <small>
                <Inbox /> From your teachers
              </small>
            </article>
          </section>
          {error && <div style={{ background: '#3c181c', color: '#ffb3ba', padding: '12px', borderRadius: '8px', marginBottom: '16px' }}>{error}</div>}
          <section className="student-main-grid">
            <div className="student-column">
              <section className="student-panel">
                <SectionHeader
                  eyebrow="Upcoming events"
                  title="Your schedule"
                  action={
                    <a className="student-link" href="/classroom">
                      Open classroom <ChevronRight />
                    </a>
                  }
                />
                <div className="student-schedule">
                  {calendarEvents.length === 0 && (
                    <p style={{ color: '#9aabc0', fontSize: '13px' }}>No upcoming calendar events scheduled.</p>
                  )}
                  {calendarEvents.map((item) => (
                    <div
                      className={`student-schedule-item ${item.type === 'ASSIGNMENT_DUE' ? 'now' : ''}`}
                      key={item.id}
                    >
                      <span className="student-time">
                        <Clock3 /> {new Date(item.startsAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}
                      </span>
                      <span className={`student-schedule-line ${item.type === 'ASSIGNMENT_DUE' ? 'amber' : 'mint'}`} />
                      <div className="student-schedule-copy">
                        <strong>{item.title}</strong>
                        <small>
                          <MapPin /> {item.type === 'ASSIGNMENT_DUE' ? 'Assignment Deadline' : item.type === 'LESSON' ? 'Scheduled Lesson' : 'Classroom Event'}
                        </small>
                      </div>
                      <Badge tone={item.type === 'ASSIGNMENT_DUE' ? 'amber' : 'mint'}>{item.type === 'ASSIGNMENT_DUE' ? 'DUE' : 'LESSON'}</Badge>
                    </div>
                  ))}
                </div>
              </section>
              <section className="student-panel">
                <SectionHeader
                  eyebrow="Stay on track"
                  title="Upcoming work"
                  action={
                    <a className="student-link" href="/student-submission-center">
                      View all work <ChevronRight />
                    </a>
                  }
                />
                <div className="student-work-list">
                  {assignments.length === 0 && (
                    <p style={{ color: '#9aabc0', fontSize: '13px' }}>No published assignments found.</p>
                  )}
                  {assignments.map((item) => (
                    <a className="student-work-item" href="/student-submission-center" key={item.id}>
                      <span className="student-work-icon mint">
                        {item.type === 'PROJECT' ? (
                          <Target />
                        ) : item.type === 'LESSON' ? (
                          <FileText />
                        ) : (
                          <BookOpen />
                        )}
                      </span>
                      <span>
                        <strong>{item.title}</strong>
                        <small>{item.points} pts {item.dueAt ? `· Due ${new Date(item.dueAt).toLocaleDateString()}` : ''}</small>
                      </span>
                      <MoreHorizontal />
                    </a>
                  ))}
                </div>
              </section>
            </div>
            <div className="student-column">
              <section className="student-panel">
                <SectionHeader
                  eyebrow="Enrolled this term"
                  title="My classes"
                  action={
                    <a className="student-panel-link" href="/classroom">
                      Classrooms <ChevronRight />
                    </a>
                  }
                />
                <label className="student-search">
                  <Search />
                  <span className="sr-only">Search classes</span>
                  <input
                    value={query}
                    onChange={(event) => setQuery(event.target.value)}
                    placeholder="Search classes"
                  />
                </label>
                <div className="student-class-list">
                  {filteredClasses.length === 0 && (
                    <p style={{ color: '#9aabc0', fontSize: '13px' }}>No classrooms match your query.</p>
                  )}
                  {filteredClasses.map((item) => (
                    <a className="student-class" href="/student-submission-center" key={item.id}>
                      <span className="class-mark mint">{item.code}</span>
                      <span>
                        <strong>{item.name}</strong>
                        <small>{item._count?.memberships ?? 0} members</small>
                      </span>
                      <ChevronRight />
                    </a>
                  ))}
                </div>
              </section>
            </div>
          </section>
        </>
      )}
      {activeTab !== 'Overview' && (
        <section className="student-empty-panel">
          <GraduationCap />
          <h2>{activeTab}</h2>
          <p>
            You have {classrooms.length} active digital classroom{classrooms.length === 1 ? '' : 's'}. You can inspect assignments and submit work directly from your Submission Center.
          </p>
          <a className="student-primary" href="/student-submission-center">
            Open Submission Center
          </a>
        </section>
      )}
      <footer className="student-footer">
        <span>
          <ShieldCheckIcon /> Your student dashboard is connected to live LMS data.
        </span>
        <span>Last synced just now</span>
      </footer>
      {showNotifications && (
        <div
          className="student-modal"
          role="dialog"
          aria-modal="true"
          aria-labelledby="student-notifications-title"
        >
          <div className="student-modal-card">
            <button
              className="student-icon-button modal-close"
              aria-label="Close notifications"
              onClick={() => setShowNotifications(false)}
            >
              <X />
            </button>
            <span className="section-kicker">Student inbox</span>
            <h2 id="student-notifications-title">Your updates</h2>
            <p>
              {unreadCount > 0
                ? `You have ${unreadCount} unread notification${unreadCount === 1 ? '' : 's'} from your teachers and classroom events.`
                : 'You have no unread notifications right now.'}
            </p>
            <a
              className="student-primary"
              href="/notifications"
              onClick={() => setShowNotifications(false)}
            >
              Open notification center
            </a>
          </div>
        </div>
      )}
    </main>
  );
}

  return (
    <main className="student-home-shell">
      <header className="student-home-header">
        <div className="student-identity">
          <div className="student-avatar">JA</div>
          <div>
            <span className="eyebrow">Tuesday, 18 March 2025 · Year 11</span>
            <h1>Good morning, Jordan.</h1>
            <p>Your learning day is ready. Here’s what needs your attention.</p>
          </div>
        </div>
        <div className="student-header-actions">
          <button
            className="student-icon-button"
            aria-label="Open notifications"
            onClick={() => setShowNotifications(true)}
          >
            <Bell />
            <i />
          </button>
          <a className="student-primary" href="/calendar">
            <CalendarDays /> Open calendar
          </a>
        </div>
      </header>
      <nav className="student-tabs" aria-label="Student dashboard sections">
        {['Overview', 'My classes', 'Progress', 'Resources'].map((tab) => (
          <button
            className={activeTab === tab ? 'active' : ''}
            key={tab}
            onClick={() => setActiveTab(tab)}
          >
            {tab}
          </button>
        ))}
      </nav>
      {activeTab === 'Overview' && (
        <>
          <section className="student-stats">
            <article>
              <span>Attendance</span>
              <strong>96%</strong>
              <small>
                <CheckCircle2 /> 2% above target
              </small>
            </article>
            <article className="mint">
              <span>Current average</span>
              <strong>88.4%</strong>
              <small>
                <TrendingUp /> Up 3.2% this term
              </small>
            </article>
            <article className="violet">
              <span>Work due</span>
              <strong>03</strong>
              <small>
                <Clock3 /> 1 due today
              </small>
            </article>
            <article className="amber">
              <span>Unread updates</span>
              <strong>04</strong>
              <small>
                <Inbox /> From your teachers
              </small>
            </article>
          </section>
          <section className="student-main-grid">
            <div className="student-column">
              <section className="student-panel">
                <SectionHeader
                  eyebrow="Tuesday schedule"
                  title="Your day"
                  action={
                    <a className="student-link" href="/calendar">
                      Full timetable <ChevronRight />
                    </a>
                  }
                />
                <div className="student-schedule">
                  {schedule.map((item) => (
                    <div
                      className={`student-schedule-item ${item.status === 'NOW' ? 'now' : ''}`}
                      key={item.title}
                    >
                      <span className="student-time">
                        <Clock3 /> {item.time}
                      </span>
                      <span className={`student-schedule-line ${item.tone}`} />
                      <div className="student-schedule-copy">
                        <strong>{item.title}</strong>
                        <small>
                          <MapPin /> {item.room}
                        </small>
                      </div>
                      <Badge tone={item.tone}>{item.status}</Badge>
                    </div>
                  ))}
                </div>
              </section>
              <section className="student-panel">
                <SectionHeader
                  eyebrow="Stay on track"
                  title="Upcoming work"
                  action={
                    <a className="student-link" href="/assignments">
                      View all <ChevronRight />
                    </a>
                  }
                />
                <div className="student-work-list">
                  {work.map((item) => (
                    <a className="student-work-item" href="/assignments" key={item.title}>
                      <span className={`student-work-icon ${item.tone}`}>
                        {item.kind === 'Quiz' ? (
                          <Target />
                        ) : item.kind === 'Essay' ? (
                          <FileText />
                        ) : (
                          <BookOpen />
                        )}
                      </span>
                      <span>
                        <strong>{item.title}</strong>
                        <small>{item.meta}</small>
                      </span>
                      <MoreHorizontal />
                    </a>
                  ))}
                </div>
              </section>
            </div>
            <div className="student-column">
              <section className="student-panel student-progress">
                <SectionHeader
                  eyebrow="Term progress"
                  title="You’re building momentum"
                  action={
                    <a className="student-panel-link" href="/results">
                      Details <ChevronRight />
                    </a>
                  }
                />
                <div className="student-score">
                  <strong>88.4</strong>
                  <span>/ 100</span>
                  <b>
                    +3.2% <small>vs last term</small>
                  </b>
                </div>
                <div className="student-progress-bar">
                  <i />
                </div>
                <div className="student-progress-footer">
                  <span>
                    <Target /> Target: 85%
                  </span>
                  <span>
                    <Sparkles /> On track
                  </span>
                </div>
                <div className="student-mini-chart" aria-label="Weekly progress chart">
                  <i style={{ height: '34%' }} />
                  <i style={{ height: '50%' }} />
                  <i style={{ height: '45%' }} />
                  <i style={{ height: '68%' }} />
                  <i style={{ height: '61%' }} />
                  <i style={{ height: '83%' }} />
                  <i style={{ height: '76%' }} />
                </div>
              </section>
              <section className="student-panel">
                <SectionHeader
                  eyebrow="Enrolled this term"
                  title="My classes"
                  action={
                    <button
                      className="student-panel-link"
                      onClick={() => setActiveTab('My classes')}
                    >
                      Manage <ChevronRight />
                    </button>
                  }
                />
                <label className="student-search">
                  <Search />
                  <span className="sr-only">Search classes</span>
                  <input
                    value={query}
                    onChange={(event) => setQuery(event.target.value)}
                    placeholder="Search classes"
                  />
                </label>
                <div className="student-class-list">
                  {filteredClasses.map((item) => (
                    <a className="student-class" href="/grades" key={item.name}>
                      <span className={`class-mark ${item.tone}`}>{item.mark}</span>
                      <span>
                        <strong>{item.name}</strong>
                        <small>{item.teacher}</small>
                      </span>
                      <ChevronRight />
                    </a>
                  ))}
                </div>
              </section>
            </div>
          </section>
        </>
      )}
      {activeTab !== 'Overview' && (
        <section className="student-empty-panel">
          <GraduationCap />
          <h2>{activeTab}</h2>
          <p>
            This student workspace is ready for the next learning module. Your current overview
            remains available from the first tab.
          </p>
          <button className="student-primary" onClick={() => setActiveTab('Overview')}>
            Return to overview
          </button>
        </section>
      )}
      <footer className="student-footer">
        <span>
          <ShieldCheckIcon /> Your dashboard is private to your account.
        </span>
        <span>Last synced just now</span>
      </footer>
      {showNotifications && (
        <div
          className="student-modal"
          role="dialog"
          aria-modal="true"
          aria-labelledby="student-notifications-title"
        >
          <div className="student-modal-card">
            <button
              className="student-icon-button modal-close"
              aria-label="Close notifications"
              onClick={() => setShowNotifications(false)}
            >
              <X />
            </button>
            <span className="section-kicker">Student inbox</span>
            <h2 id="student-notifications-title">Your updates</h2>
            <p>
              Ms. Adeyemi shared feedback on your mathematics submission. Your next class starts in
              12 minutes.
            </p>
            <a
              className="student-primary"
              href="/notifications"
              onClick={() => setShowNotifications(false)}
            >
              Open notification center
            </a>
          </div>
        </div>
      )}
    </main>
  );
}
function ShieldCheckIcon() {
  return <CheckCircle2 />;
}

import { useCallback, useEffect, useState } from 'react';
import {
  AlertTriangle,
  ArrowRight,
  BookOpen,
  BriefcaseBusiness,
  CalendarDays,
  CheckCircle2,
  ChevronRight,
  ClipboardCheck,
  FileText,
  GraduationCap,
  Plus,
  RefreshCw,
  Users,
  UserRound,
} from 'lucide-react';
import api from './api/auth.js';
import { getApiErrorMessage } from './api/errorMessage.js';

export default function TeacherDashboard() {
  const [teacher, setTeacher] = useState(null);
  const [classrooms, setClassrooms] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [schoolId, setSchoolId] = useState(() => sessionStorage.getItem('sais.schoolId') || '');

  const headers = schoolId ? { 'x-school-id': schoolId } : {};

  const loadDashboard = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [teacherRes, classroomsRes] = await Promise.allSettled([
        api.get('/teachers/me'),
        api.get('/lms/classrooms', { headers }),
      ]);

      if (teacherRes.status === 'fulfilled') {
        setTeacher(teacherRes.value.data.data);
      } else {
        setError(getApiErrorMessage(teacherRes.reason, 'Unable to load teacher profile'));
      }

      if (classroomsRes.status === 'fulfilled') {
        const rooms = classroomsRes.value.data.data || [];
        setClassrooms(rooms);

        if (rooms.length > 0) {
          const assignmentRequests = rooms.slice(0, 3).map((room) =>
            api.get('/lms/assignments', {
              headers,
              params: { classroomId: room.id },
            })
          );
          const assignmentResults = await Promise.allSettled(assignmentRequests);
          const allAssignments = assignmentResults
            .filter((res) => res.status === 'fulfilled')
            .flatMap((res) => res.value.data.data || []);
          setAssignments(allAssignments);
        }
      }
    } catch (requestError) {
      setError(getApiErrorMessage(requestError, 'Unable to load teacher workspace'));
    } finally {
      setLoading(false);
    }
  }, [schoolId]);

  useEffect(() => {
    sessionStorage.setItem('sais.schoolId', schoolId);
    loadDashboard();
  }, [loadDashboard, schoolId]);

  return (
    <main className="teacher-shell">
      <header className="teacher-header">
        <div>
          <p className="eyebrow">SAIS · Teacher workspace</p>
          <h1>
            {teacher
              ? `${teacher.profile?.firstName ?? ''} ${teacher.profile?.lastName ?? ''}`.trim() || 'Teacher profile'
              : 'Teacher profile'}
          </h1>
          <p>Your verified employment identity, assigned learning spaces, and active classwork.</p>
        </div>
        <button
          className="secondary-button"
          onClick={loadDashboard}
          disabled={loading}
          type="button"
          style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}
        >
          <RefreshCw size={15} /> Refresh
        </button>
      </header>

      {error && (
        <section className="teacher-panel" role="alert" style={{ marginBottom: '16px' }}>
          <AlertTriangle size={18} /> {error}
        </section>
      )}

      {teacher && (
        <section className="teacher-stats">
          <article className="teacher-panel">
            <UserRound size={18} />
            <span>Employee number</span>
            <strong>{teacher.employeeNumber}</strong>
          </article>
          <article className="teacher-panel">
            <BriefcaseBusiness size={18} />
            <span>Employment</span>
            <strong>{teacher.employment?.jobTitle ?? 'Not recorded'}</strong>
          </article>
          <article className="teacher-panel">
            <BookOpen size={18} />
            <span>Active learning spaces</span>
            <strong>{classrooms.length} classroom{classrooms.length === 1 ? '' : 's'}</strong>
          </article>
        </section>
      )}

      <section className="teacher-panel" style={{ marginBottom: '20px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
          <div>
            <h2>Digital Classrooms</h2>
            <p>Your assigned learning spaces and member counts.</p>
          </div>
          <a className="primary-button" href="/classroom" style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '13px', padding: '8px 12px' }}>
            <Plus size={15} /> Open classroom workspace
          </a>
        </div>

        {loading && <p className="loading-state">Loading classrooms...</p>}
        {!loading && classrooms.length === 0 && (
          <p className="empty-state">No digital classrooms found for your account. Create or join a classroom to manage classwork.</p>
        )}
        {!loading && classrooms.length > 0 && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '12px' }}>
            {classrooms.map((room) => (
              <div
                key={room.id}
                style={{
                  border: '1px solid #274663',
                  borderRadius: '12px',
                  background: '#0d1b2e',
                  padding: '16px',
                  display: 'flex',
                  flexDirection: 'column',
                  justify: 'space-between',
                  gap: '12px',
                }}
              >
                <div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <strong style={{ fontSize: '16px', color: '#e8eef7' }}>{room.name}</strong>
                    <span style={{ fontSize: '11px', color: '#48d8c9', background: '#12383c', padding: '2px 8px', borderRadius: '4px' }}>{room.code}</span>
                  </div>
                  {room.description && <p style={{ fontSize: '13px', color: '#9aabc0', margin: '6px 0 0' }}>{room.description}</p>}
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderTop: '1px solid #1f374e', paddingTop: '10px' }}>
                  <span style={{ fontSize: '12px', color: '#9aabc0', display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
                    <Users size={14} /> {room._count?.memberships ?? 0} members
                  </span>
                  <a href="/classroom" style={{ color: '#48d8c9', fontSize: '13px', textDecoration: 'none', fontWeight: 600, display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
                    View <ChevronRight size={14} />
                  </a>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      {assignments.length > 0 && (
        <section className="teacher-panel" style={{ marginBottom: '20px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '14px' }}>
            <div>
              <h2>Classwork & Assignments</h2>
              <p>Recent assignments across your digital classrooms.</p>
            </div>
            <a href="/gradebook" style={{ color: '#48d8c9', fontSize: '13px', textDecoration: 'none', fontWeight: 600, display: 'inline-flex', alignItems: 'center', gap: '4px' }}>
              Gradebook <ChevronRight size={14} />
            </a>
          </div>
          <div style={{ display: 'grid', gap: '8px' }}>
            {assignments.slice(0, 5).map((item) => (
              <div
                key={item.id}
                style={{
                  border: '1px solid #274663',
                  borderRadius: '8px',
                  background: '#0b1b2e',
                  padding: '12px 16px',
                  display: 'flex',
                  justify: 'space-between',
                  alignItems: 'center',
                }}
              >
                <div>
                  <strong style={{ color: '#edf5ff', display: 'block' }}>{item.title}</strong>
                  <span style={{ fontSize: '12px', color: '#9cb2cb' }}>
                    {item.type} · {item.points} pts {item.dueAt ? `· Due ${new Date(item.dueAt).toLocaleDateString()}` : ''}
                  </span>
                </div>
                <span
                  style={{
                    fontSize: '11px',
                    fontWeight: 700,
                    padding: '3px 8px',
                    borderRadius: '4px',
                    background: item.status === 'PUBLISHED' ? '#12383c' : '#28445f',
                    color: item.status === 'PUBLISHED' ? '#21c4c9' : '#bdd2e9',
                  }}
                >
                  {item.status}
                </span>
              </div>
            ))}
          </div>
        </section>
      )}

      <section className="teacher-panel">
        <h2>Teaching workspace</h2>
        <p>Open the tools used for daily teaching, assessment, and learner support.</p>
        <div className="teacher-action-grid">
          <a href="/classroom">
            <GraduationCap size={18} />
            <span>
              <strong>Digital Classrooms</strong>
              <small>Classrooms, streams, and classwork</small>
            </span>
          </a>
          <a href="/student-submission-center">
            <FileText size={18} />
            <span>
              <strong>Submissions & Work</strong>
              <small>Review student versioned submissions</small>
            </span>
          </a>
          <a href="/timetables">
            <CalendarDays size={18} />
            <span>
              <strong>Timetable</strong>
              <small>Lessons and schedules</small>
            </span>
          </a>
          <a href="/attendance">
            <ClipboardCheck size={18} />
            <span>
              <strong>Attendance</strong>
              <small>Open and mark registers</small>
            </span>
          </a>
          <a href="/gradebook">
            <BookOpen size={18} />
            <span>
              <strong>Gradebook</strong>
              <small>Marks, rubrics, and feedback</small>
            </span>
          </a>
        </div>
      </section>
    </main>
  );
}
